function startStage1(){document.getElementById("timer").textContent="";let n=0,e=15;const t=[{name:"🖥 ECG Monitor",status:"ECG ONLINE",correct:!0},{name:"⚡ Defibrillator",status:"DEFIB READY",correct:!0},{name:"💨 Ventilator",status:"VENTILATOR READY",correct:!0},{name:"🧰 Crash Cart",status:"CRASH CART READY",correct:!0},{name:"🎮 PlayStation",correct:!1},{name:"🍳 Air Fryer",correct:!1},{name:"📺 TV",correct:!1},{name:"🧹 Vacuum Cleaner",correct:!1}];shuffle(t),stageContent.innerHTML=`\n\n        <div class="card stage-one">\n\n            <h1>\n                🚨 Resuscitation Room Setup\n            </h1>\n\n\n            <p class="stage-description">\n\n                A critical patient has arrived.\n                Prepare all required medical equipment.\n\n            </p>\n\n\n            <div class="patient-monitor">\n\n                <h3>\n                    Patient Status\n                </h3>\n\n                <p>\n                    ❤️ Heart Rate:\n                    <span>0 bpm</span>\n                </p>\n\n                <p>\n                    🫁 SpO₂:\n                    <span>68%</span>\n                </p>\n\n                <p>\n                    ⚠ Condition:\n                    <span>\n                        CRITICAL\n                    </span>\n                </p>\n\n            </div>\n\n\n            <div\n                id="stage-timer"\n                class="timer-box">\n\n                ${e}\n\n            </div>\n\n\n            <div class="devices-grid">\n\n                ${t.map(((n,e)=>`\n\n                        <div\n                            class="device-card"\n                            data-index="${e}">\n\n                            ${n.name}\n\n                        </div>\n\n                        `)).join("")}\n\n            </div>\n\n\n            <div\n                id="status"\n                class="status-box">\n\n                Equipment required: 4\n\n            </div>\n\n\n        </div>\n\n    `;const a=document.getElementById("stage-timer"),r=document.getElementById("status"),i=setInterval((()=>{e--,a.textContent=e,e<=0&&(clearInterval(i),gameOver("Time expired. Patient condition worsened."))}),1e3);document.querySelectorAll(".device-card").forEach((e=>{e.addEventListener("click",(()=>{if(e.classList.contains("correct")||e.classList.contains("wrong"))return;const a=t[e.dataset.index];a.correct?(e.classList.add("correct"),e.innerHTML=`\n                        ${a.name}\n\n                        <br>\n\n                        <small>\n                            ${a.status}\n                        </small>\n\n                        `,n++,r.textContent=`\n                        ${n}/4 equipment ready\n                        `,playSound("success"),4===n&&(clearInterval(i),transition("✅ RESUSCITATION ROOM READY","All critical equipment is operational. Connecting ECG Monitor...",(()=>{updatePatientState("unstable"),stageCompleted()})))):(e.classList.add("wrong"),playSound("failure"),gameOver("❌ Wrong equipment selected.<br><br>Medical preparation failed."))}))}))}